import{_ as t,o as a,c as o,a8 as i}from"./chunks/framework.CNIpabDg.js";const u=JSON.parse('{"title":"Write or update documentation","description":"Choose a documentation type, write a focused Xila page, and validate its links and build.","frontmatter":{"layout":"doc","docType":"how-to","description":"Choose a documentation type, write a focused Xila page, and validate its links and build."},"headers":[],"relativePath":"how-to/write-documentation.md","filePath":"how-to/write-documentation.md","lastUpdated":1793145952000}'),r={name:"how-to/write-documentation.md"};function n(s,e,d,c,l,p){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[...e[0]||(e[0]=[i(`<h1 id="write-or-update-documentation" tabindex="-1">Write or update documentation <a class="header-anchor" href="#write-or-update-documentation" aria-label="Permalink to &quot;Write or update documentation&quot;">​</a></h1><p>Add a page or revise an existing one so readers can learn, complete a task, look up a fact, or understand a design.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Work in the <code>website</code> repository with its Node.js/npm environment. Read <a href="https://github.com/xila-project/website/blob/main/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> and check the relevant Core, Applications or Platforms source at a known revision for technical claims.</p><h2 id="choose-the-page-s-purpose" tabindex="-1">Choose the page&#39;s purpose <a class="header-anchor" href="#choose-the-page-s-purpose" aria-label="Permalink to &quot;Choose the page&#39;s purpose&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reader&#39;s need</th><th>Type</th><th>Directory</th></tr></thead><tbody><tr><td>Learn through a guided example</td><td>Tutorial</td><td><code>src/tutorials/</code></td></tr><tr><td>Complete an independent task</td><td>How-to</td><td><code>src/how-to/</code></td></tr><tr><td>Look up exact options, defaults, errors, or APIs</td><td>Reference</td><td><code>src/reference/</code></td></tr><tr><td>Understand a concept, relationship, or trade-off</td><td>Explanation</td><td><code>src/explanation/</code></td></tr></tbody></table><p>The structure follows <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a>. Local writing templates are informed by <a href="https://github.com/thegooddocsproject/templates" target="_blank" rel="noreferrer">The Good Docs Project</a>.</p><h2 id="write-the-page" tabindex="-1">Write the page <a class="header-anchor" href="#write-the-page" aria-label="Permalink to &quot;Write the page&quot;">​</a></h2><ol><li>Copy the appropriate file from <a href="https://github.com/xila-project/website/tree/main/docs/templates" target="_blank" rel="noreferrer">docs/templates</a> into the selected source directory.</li><li>Replace the title, description, and all writing prompts. Keep the correct <code>docType</code> value and remove unused sections.</li><li>State who the page helps and what they will achieve. Put environment/artifact prerequisites before procedural steps.</li><li>Specify each command&#39;s directory and whether it runs in the host shell, Devbox shell, browser console, or Xila terminal.</li><li>Add observable results to tutorials and completion checks to task guides. Keep exact lookup tables in reference pages and design reasoning in explanations.</li><li>Link to related page types instead of duplicating their procedures or reference tables.</li></ol><p>Keep the published content in English and preserve technical identifiers exactly. Do not claim commands, hardware support, or runtime behavior were verified unless they actually were.</p><h2 id="make-explanation-pages-progressive" tabindex="-1">Make Explanation pages progressive <a class="header-anchor" href="#make-explanation-pages-progressive" aria-label="Permalink to &quot;Make Explanation pages progressive&quot;">​</a></h2><p>Explanation should help a reader build a mental model before asking them to understand implementation details. Prefer a <strong>cognitive order</strong>, not a mandatory heading template:</p><ol><li>explain what the concept/component is and why Xila needs it;</li><li>give a short mental model or faithful analogy when it helps;</li><li>show how it relates to neighboring parts of Xila;</li><li>describe one concrete interaction in narrative form;</li><li>introduce the few Rust abstractions that embody the design;</li><li>move current data structures, locks, runner loops, and other internals into a deeper section such as <code>Under the hood</code>;</li><li>finish with the architectural consequences, trade-offs, boundaries, and deliberate links to related documentation.</li></ol><p>Do not turn the concrete interaction into a setup procedure. For example, an Explanation page can describe what happens when an executable opens <code>/data/config.json</code>, but the reader should not be instructed to perform those steps. If the reader&#39;s next question is <em>how do I do this?</em>, link to a How-to or Tutorial instead.</p><p>Likewise, avoid reproducing exhaustive error lists, option tables, command matrices, or method inventories. Keep facts that explain a boundary or trade-off, then point to Reference/Rustdoc for exact lookup detail.</p><h3 id="use-diagrams-to-teach-one-idea" tabindex="-1">Use diagrams to teach one idea <a class="header-anchor" href="#use-diagrams-to-teach-one-idea" aria-label="Permalink to &quot;Use diagrams to teach one idea&quot;">​</a></h3><p>For introductory Mermaid diagrams:</p><ul><li>show one relationship or flow at a time;</li><li>normally keep the diagram to roughly 4–7 primary nodes;</li><li>prefer human labels (<code>Task manager</code>, <code>Interface stack</code>, <code>Platform driver</code>) over Rust implementation names;</li><li>keep <code>RwLock</code>, <code>BTreeMap</code>, <code>StackInner</code>, refcounts, and similar internals out of the first diagram;</li><li>explain in prose what the reader should notice after the diagram.</li></ul><p><code>flowchart LR</code> works well for architecture/ownership relationships, while <code>sequenceDiagram</code> is useful for describing a concrete request journey. A second implementation-level diagram may use exact Rust types once the page has established the conceptual model.</p><h3 id="link-rustdoc-at-the-point-of-explanation" tabindex="-1">Link Rustdoc at the point of explanation <a class="header-anchor" href="#link-rustdoc-at-the-point-of-explanation" aria-label="Permalink to &quot;Link Rustdoc at the point of explanation&quot;">​</a></h3><p>Use <code>HostReference</code> and <code>GuestReference</code> inline when a public Rust symbol gives precision to the concept being discussed. The surrounding sentence must still explain what the symbol means; readers should not need to click the link to understand the page.</p><p>A reference can target a crate, a top-level Rustdoc symbol, or an associated-item anchor. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;HostReference crate=&quot;virtual_file_system&quot; kind=&quot;struct&quot; symbol=&quot;File&quot; member=&quot;method.open&quot;&gt;opening a file&lt;/HostReference&gt;</span></span></code></pre></div><p><code>member</code> is the raw Rustdoc anchor (for example <code>method.open</code>, <code>associatedconstant.NAME</code>, or <code>associatedtype.Item</code>), not a website-specific taxonomy. Only use it after verifying the generated symbol/anchor. Keep <code>CodeReference</code> for source or example code whose implementation materially helps the explanation, rather than linking source merely because it exists.</p><h3 id="source-repositories-after-the-split" tabindex="-1">Source repositories after the split <a class="header-anchor" href="#source-repositories-after-the-split" aria-label="Permalink to &quot;Source repositories after the split&quot;">​</a></h3><p><code>CodeReference</code> defaults to Core. Set <code>repo=&quot;applications&quot;</code> for Wasmi and official executable sources, or <code>repo=&quot;platforms&quot;</code> for platform drivers, examples and deployment files. For an exact moved file, use its full path relative to that repository&#39;s root.</p><p><code>HostReference</code> and <code>GuestReference</code> also accept <code>repo</code>. Core host references still use the deployed Rustdoc viewer. Because external Applications/Platforms Rustdoc is not deployed at the former Core Pages URLs, those references link to the crate&#39;s GitHub source directory rather than a symbol-specific page.</p><p>CI checks paths against current Core, Applications and Platforms checkouts. Locally, provide <code>XILA_CORE_PATH</code>, <code>XILA_APPLICATIONS_PATH</code> and <code>XILA_PLATFORMS_PATH</code> to enable all source checks.</p><h2 id="connect-the-page" tabindex="-1">Connect the page <a class="header-anchor" href="#connect-the-page" aria-label="Permalink to &quot;Connect the page&quot;">​</a></h2><p>Update its section landing page and <code>.vitepress/navigation.ts</code>. Link to it from relevant existing pages and the <a href="/explanation/architecture/components.html">component map</a> when appropriate.</p><p>When moving a page, update incoming links and anchors. The site is pre-production; the current workflow moves pages directly without legacy redirects.</p><p>For API/source links, use the existing <code>HostReference</code>, <code>GuestReference</code>, and <code>CodeReference</code> components after checking their crate, symbol, member anchor, or source path. Keep templates outside <code>src/</code> so writing prompts never appear in the public site or search.</p><h2 id="validate-the-change" tabindex="-1">Validate the change <a class="header-anchor" href="#validate-the-change" aria-label="Permalink to &quot;Validate the change&quot;">​</a></h2><p>From the website repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:fix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p><code>check</code> verifies Rustdoc-reference path behavior, formatting, the production site/search build, and documentation links/anchors. Review <code>format:fix</code>&#39;s diff; for a focused change, run Prettier on only the changed files instead.</p><p>Preview the production build with <code>npm run docs:preview</code>, check the navigation and reader journey, then run <code>git diff --check</code>.</p><p>For an Explanation rewrite, also compare the old and new page specifically for <strong>technical fact loss</strong>. Every removed implementation fact should either still exist deeper in the page, be deliberately replaced by an authoritative Reference/Rustdoc link, or be intentionally removed because it was stale or did not help explain the design.</p><h2 id="verify-completion" tabindex="-1">Verify completion <a class="header-anchor" href="#verify-completion" aria-label="Permalink to &quot;Verify completion&quot;">​</a></h2><p>The page should be discoverable from its section, satisfy one primary reader need, and have no unresolved writing prompts or broken internal links. Explanation pages should establish their mental model before implementation internals. Review the diff for technical facts lost during splitting, and state which checks actually ran.</p>`,40)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
